import {basename,dirname} from 'node:path';
import {V1Database} from '../../src/database.js';
import {CommerceService} from '../../src/commerce.js';
import {createMigrationApprovalAuthority} from '../../src/migration-auth.js';
import {createRolloutApprovalAuthority} from '../../src/rollout-auth.js';
import {createStaffCapabilityAuthority} from '../../src/staff-auth.js';
import {StaffConversationControl} from '../../src/staff-conversation-control.js';
import {V2RolloutService} from '../../src/v2-rollout.js';
import {V2CanaryIngressRouter} from '../../src/v2-canary-ingress-router.js';
import {AccountInquiryController} from '../../src/account-inquiry-policy.js';
const file=process.argv[2];if(!file||!basename(dirname(file)).startsWith('waerp-staff-crash-'))throw Error('ISOLATED_SYNTHETIC_DB_REQUIRED');
const migration=createMigrationApprovalAuthority(),approval=createRolloutApprovalAuthority(),db=new V1Database(file,migration,approval),staff=createStaffCapabilityAuthority();
let controller!:AccountInquiryController;
const control=new StaffConversationControl(db,staff.verify,{accountId:'demo-account',enabled:()=>true,inFlight:s=>controller?.isInFlight(s)??false});
const commerce=new CommerceService(db),rollout=new V2RolloutService(db,approval),router=new V2CanaryIngressRouter(db,commerce,rollout,{enabled:true,outbound:{send:async()=>{throw Error('CRASH_FIXTURE_SEND_FORBIDDEN')}} as any,prospectModel:async()=>{throw Error('CRASH_FIXTURE_MODEL_FORBIDDEN')},verifyInquiryAdmission:(t,c)=>controller.verifyAdmission(t,c)});
controller=new AccountInquiryController(db,'demo-account',router,migration,rollout,approval,control);
db.db.function('synthetic_crash',()=>process.exit(86));
db.db.exec("CREATE TRIGGER synthetic_crash BEFORE INSERT ON messages WHEN NEW.external_message_id='synthetic-held-crash' BEGIN SELECT synthetic_crash(); END");
await controller.receiveFromChannel({accountId:'demo-account',conversationId:'65000000002@s.whatsapp.net',externalMessageId:'synthetic-held-crash',channel:'whatsapp',sender:{externalId:'65000000002@s.whatsapp.net',phone:'+65000000002'},type:'text',text:'Synthetic crash-held inbound',occurredAt:new Date(Date.now()+10).toISOString()});
throw Error('CRASH_FIXTURE_DID_NOT_REACH_FAULT');
